('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Use Case beschreibt eine Interaktion mit dem System. b) Jeder Use Case hat genau einen Aktor.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Interaktion ist zentral, mehrere Aktoren möglich"}, {"text": "Beides stimmt", "correct": false, "because": "Mehrere Aktoren erlaubt"}, {"text": "Nur b) stimmt", "correct": false, "because": "Interaktion ist Kern"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehung in einem Use-Case-Diagramm zeigt eine optionale Erweiterung?', 4, '[{"text": "Extend", "correct": true, "because": "Zeigt optionale Use Cases"}, {"text": "Include", "correct": false, "because": "Zeigt zwingende Einbindung"}, {"text": "Association", "correct": false, "because": "Nur Verbindung zwischen Aktor und Use Case"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Use-Case-Diagramm ohne Systemgrenze erstellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Grenze ist optional"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend erforderlich"}]');
